import { addAPIProvider, addCollection } from '@iconify/vue';
import type { IconifyJSON } from '@iconify/types';

/** Setup the iconify offline */
export async function setupIconifyOffline() {
  const { VITE_ICONIFY_URL } = import.meta.env;

  if (VITE_ICONIFY_URL) {
    addAPIProvider('', { resources: [VITE_ICONIFY_URL] });
    return;
  }

  // Only the icons in scripts/icons.txt are bundled (generated by
  // scripts/gen-icons.mjs before build). Importing the full mdi set costs ~3MB.
  const mod = await import('./icons.json');

  addCollection(mod.default as IconifyJSON);
}
